package xapi.jre.model;
import org.junit.Test;import static org.junit.Assert.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.atomic.AtomicReference;
/** Exact-image prerequisites and two-record receipts using real synthetic files. */
public class ModelAtomicCompletionStoreTest {
 static ModelStoreKey key(String id){return new ModelStoreKey(id,"models/"+id);}
 static byte[] bytes(String s){return s.getBytes(StandardCharsets.UTF_8);}
 static ModelTransaction tx(String op,ModelMutation... mutations){return new ModelTransaction("complete-test-v1","schema-v1","actor",op,Arrays.asList(mutations));}
 static ModelReadCondition condition(FileModelTransactionStore s,ModelStoreKey k)throws Exception{return new ModelReadCondition(k,s.read(k));}
 static void legacy(FileModelTransactionStore s,ModelStoreKey k,String value)throws Exception{s.legacyWriteScope(k,()->{Path p=s.directory().resolve(k.relativePath());Files.createDirectories(p.getParent());Files.write(p,bytes(value));return null;});}
 static void conflict(Action r)throws Exception{try{r.run();fail("expected conflict");}catch(FileModelTransactionStore.Conflict expected){}}
 interface Action{void run()throws Exception;}
 @Test public void revisionZeroImageChangeRejectsBothWrites()throws Exception{try(FileModelTransactionStore s=new FileModelTransactionStore(Files.createTempDirectory("atomic-image"))){ModelStoreKey live=key("live"),history=key("history");legacy(s,live,"ACTIVE");ModelReadCondition before=condition(s,live),missing=condition(s,history);legacy(s,live,"OTHER-ACTIVE");conflict(()->s.commitIfUnchanged(tx("a",new ModelMutation(live,0,bytes("FINISHED")),new ModelMutation(history,-1,bytes("HISTORY"))),Arrays.asList(before,missing)));assertEquals("OTHER-ACTIVE",new String(s.read(live).value(),StandardCharsets.UTF_8));assertFalse(s.read(history).exists());assertNull(s.receipt("actor","a"));}}
 @Test public void changedPrerequisiteOrOptionalAbsenceRejects()throws Exception{try(FileModelTransactionStore s=new FileModelTransactionStore(Files.createTempDirectory("atomic-prerequisite"))){ModelStoreKey live=key("live"),history=key("history"),child=key("child");legacy(s,live,"ACTIVE");List<ModelReadCondition> conditions=Arrays.asList(condition(s,live),condition(s,history),condition(s,child));legacy(s,child,"ACTIVE");conflict(()->s.commitIfUnchanged(tx("a",new ModelMutation(live,0,bytes("FINISHED")),new ModelMutation(history,-1,bytes("HISTORY"))),conditions));assertFalse(s.read(history).exists());}}
 @Test public void identicalReceiptWinsOverObsoleteConditionsAcrossRestart()throws Exception{Path root=Files.createTempDirectory("atomic-retry");ModelTransaction transaction=tx("same",new ModelMutation(key("live"),-1,bytes("FINISHED")),new ModelMutation(key("history"),-1,bytes("TIME123")));ModelTransactionReceipt first;List<ModelReadCondition> conditions;try(FileModelTransactionStore s=new FileModelTransactionStore(root)){conditions=Arrays.asList(condition(s,key("live")),condition(s,key("history")));first=s.commitIfUnchanged(transaction,conditions);assertTrue(s.isProtected(key("live")));conflict(()->legacy(s,key("live"),"ACTIVE"));}try(FileModelTransactionStore s=new FileModelTransactionStore(root)){ModelTransactionReceipt retry=s.commitIfUnchanged(transaction,conditions);assertEquals(first.fingerprint(),retry.fingerprint());assertEquals(first.revision(),retry.revision());conflict(()->s.commitIfUnchanged(tx("same",new ModelMutation(key("live"),-1,bytes("DIFFERENT"))),conditions));}}
 @Test public void concurrentConditionalBundlesHaveOneWholeWinner()throws Exception{try(FileModelTransactionStore s=new FileModelTransactionStore(Files.createTempDirectory("atomic-concurrent"))){List<ModelReadCondition> conditions=Arrays.asList(condition(s,key("live")),condition(s,key("history")));AtomicReference<Throwable> unexpected=new AtomicReference<>();java.util.concurrent.atomic.AtomicInteger wins=new java.util.concurrent.atomic.AtomicInteger(),conflicts=new java.util.concurrent.atomic.AtomicInteger();List<Thread> threads=new ArrayList<>();for(String id:new String[]{"a","b"}){Thread t=new Thread(()->{try{s.commitIfUnchanged(tx(id,new ModelMutation(key("live"),-1,bytes(id)),new ModelMutation(key("history"),-1,bytes(id))),conditions);wins.incrementAndGet();}catch(FileModelTransactionStore.Conflict e){conflicts.incrementAndGet();}catch(Throwable e){unexpected.set(e);}});threads.add(t);t.start();}for(Thread t:threads){t.join(5000);assertFalse(t.isAlive());}assertNull(unexpected.get());assertEquals(1,wins.get());assertEquals(1,conflicts.get());assertArrayEquals(s.read(key("live")).value(),s.read(key("history")).value());}}
 @Test public void missingCoverageAliasesAndProtectedMissingFailClosed()throws Exception{try(FileModelTransactionStore s=new FileModelTransactionStore(Files.createTempDirectory("atomic-invalid"))){ModelStoreKey live=key("live");ModelTransaction t=tx("a",new ModelMutation(live,-1,bytes("F")));try{s.commitIfUnchanged(t,Collections.emptyList());fail();}catch(java.io.IOException expected){}ModelReadCondition absent=condition(s,live);try{s.commitIfUnchanged(t,Arrays.asList(absent,new ModelReadCondition(new ModelStoreKey("alias",live.relativePath()),s.read(live))));fail();}catch(java.io.IOException expected){}s.commitIfUnchanged(t,Arrays.asList(absent));Files.delete(s.directory().resolve(live.relativePath()));try{s.commitIfUnchanged(tx("b",new ModelMutation(live,1,bytes("F"))),Arrays.asList(absent));fail();}catch(java.io.IOException expected){}assertFalse(Files.exists(s.directory().resolve(live.relativePath())));}}
 @Test public void concurrentIdenticalOperationReturnsSameReceipt()throws Exception {
  try(FileModelTransactionStore store=new FileModelTransactionStore(Files.createTempDirectory("atomic-same-op"))){
   List<ModelReadCondition> conditions=Arrays.asList(condition(store,key("live")),condition(store,key("history")));
   ModelTransaction transaction=tx("same",new ModelMutation(key("live"),-1,bytes("FINISHED")),new ModelMutation(key("history"),-1,bytes("TIME123")));
   AtomicReference<ModelTransactionReceipt> first=new AtomicReference<>(),second=new AtomicReference<>();AtomicReference<Throwable> error=new AtomicReference<>();
   Thread a=new Thread(()->{try{first.set(store.commitIfUnchanged(transaction,conditions));}catch(Throwable e){error.set(e);}}),b=new Thread(()->{try{second.set(store.commitIfUnchanged(transaction,conditions));}catch(Throwable e){error.set(e);}});a.start();b.start();a.join(5000);b.join(5000);assertFalse(a.isAlive());assertFalse(b.isAlive());assertNull(error.get());assertEquals(first.get().fingerprint(),second.get().fingerprint());assertEquals(first.get().revision(),second.get().revision());
  }
 }
 @Test public void publishedUncertainOutcomeRecoversOriginalReceiptWithoutNewPreparation()throws Exception {
  Path root=Files.createTempDirectory("atomic-uncertain");java.util.concurrent.atomic.AtomicBoolean injected=new java.util.concurrent.atomic.AtomicBoolean();
  ModelTransaction transaction=tx("uncertain",new ModelMutation(key("live"),-1,bytes("FINISHED")),new ModelMutation(key("history"),-1,bytes("ORIGINAL-TIME")));List<ModelReadCondition> conditions;
  try(FileModelTransactionStore store=new FileModelTransactionStore(root,(boundary,child)->{if(boundary==FileModelTransactionStore.Boundary.COMMITTED&&injected.compareAndSet(false,true))throw new java.io.IOException("injected after publication");})){
   conditions=Arrays.asList(condition(store,key("live")),condition(store,key("history")));try{store.commitIfUnchanged(transaction,conditions);fail();}catch(FileModelTransactionStore.RecoveryRequired expected){}try{store.read(key("live"));fail();}catch(FileModelTransactionStore.RecoveryRequired expected){}
  }
  try(FileModelTransactionStore store=new FileModelTransactionStore(root)){ModelTransactionReceipt receipt=store.commitIfUnchanged(transaction,conditions);assertEquals(1,receipt.revision());assertArrayEquals(bytes("ORIGINAL-TIME"),store.read(key("history")).value());assertEquals(receipt.fingerprint(),store.receipt("actor","uncertain").fingerprint());}
 }
 @Test public void excessiveConditionCountAndAggregateImageAreRejectedBeforeCommit()throws Exception {
  try(FileModelTransactionStore store=new FileModelTransactionStore(Files.createTempDirectory("atomic-condition-limits"))){
   List<ModelReadCondition> tooMany=new ArrayList<>();for(int i=0;i<=FileModelTransactionStore.MAX_MUTATIONS;i++)tooMany.add(condition(store,key("key"+i)));
   ModelTransaction transaction=tx("bounded",new ModelMutation(key("key0"),-1,bytes("value")));try{store.commitIfUnchanged(transaction,tooMany);fail();}catch(java.io.IOException expected){}
   byte[] halfPlusOne=new byte[FileModelTransactionStore.MAX_REQUEST_BYTES/2+1];List<ModelReadCondition> oversized=Arrays.asList(new ModelReadCondition(key("key0"),new ModelStoreRecord(halfPlusOne,0)),new ModelReadCondition(key("extra"),new ModelStoreRecord(halfPlusOne,0)));
   try{store.commitIfUnchanged(transaction,oversized);fail();}catch(java.io.IOException expected){}assertNull(store.receipt("actor","bounded"));assertFalse(store.read(key("key0")).exists());
  }
 }

}
